L.STRINGS = {
	["120 Merchant's Favor"] = "120 Gunst des Händlers",
	["1200 Merchant's Favor"] = "1200 Gunst des Händlers",
	["1500 Merchant's Favor"] = "1500 Gunst des Händlers",
	["180 Merchant's Favor"] = "180 Gunst des Händlers",
	["200 Merchant's Favor"] = "200 Gunst des Händlers",
	["240 Merchant's Favor"] = "240 Gunst des Händlers",
	["270 Merchant's Favor"] = "270 Gunst des Händlers",
	["360 Merchant's Favor"] = "360 Gunst des Händlers",
	["60 Merchant's Favor"] = "60 Gunst des Händlers",
	["6000 Merchant's Favor"] = "6000 Gunst des Händlers",
	["90 Merchant's Favor"] = "90 Gunst des Händlers",
	["A 1.5-second cast: a 3-minute curse that hurts the player now and then when they attack. Remove it."] = "1.5 Sekunden Zauberzeit: ein Fluch für 3 Minuten, der dem Spieler bei Angriffen ab und zu Schaden zufügt. Entfernt ihn.",
	["A 2-second cast, then for 6 seconds arcane energy hits everyone within 25 yards every 2 seconds, for about 140 damage each time. Ranged players, stay beyond 25 yards; melee, step out during the cast."] = "2 Sekunden Zauberzeit, dann trifft arkane Energie 6 Sekunden lang alle 2 Sekunden jeden im Umkreis von 25 Metern, für jeweils etwa 140 Schaden. Fernkämpfer, bleibt über 25 Meter entfernt. Nahkämpfer, tretet während des Zaubers heraus.",
	["A 2-second cast: a hit, then Nature damage for a minute. Cure the poison."] = "2 Sekunden Zauberzeit: ein Treffer, dann eine Minute lang Naturschaden. Heilt die Vergiftung.",
	["A 2-second cast: arcane power drains up to 200 mana from everyone within 45 yards of him."] = "2 Sekunden Zauberzeit: Arkane Macht entzieht allen im Umkreis von 45 Metern um ihn bis zu 200 Mana.",
	["A 3-second Shadow bolt on the tank, over and over. Interrupt it."] = "Ein Schattenblitz mit 3 Sekunden Zauberzeit auf den Tank, immer wieder. Unterbrecht ihn.",
	["A Binding Contract"] = "Ein bindender Vertrag",
	["A Blackrock orc who can be found in one of four cells."] = "Ein Orc der Schwarzfelsen, der in einer von vier Zellen zu finden ist.",
	["A Broken Trap"] = "Eine kaputte Falle",
	["A Crumpled Up Note"] = "Eine zusammengeknüllte Notiz",
	["A Dark Iron dwarf held for his part in the Thandol Span attacks."] = "Ein Dunkeleisenzwerg, der wegen seiner Rolle bei den Angriffen auf den Thandolübergang einsitzt.",
	["A Dynamite Plan"] = "Ein Plan mit Dynamit",
	["A Fanglord who turns into a serpent partway through the fight."] = "Ein Giftzahnlord, der sich im Lauf des Kampfes in eine Schlange verwandelt.",
	["A Fine Mess"] = "Ein schöner Schlamassel",
	["A Frightened Request"] = "Eine verängstigte Bitte",
	["A Green Sample"] = "Eine grüne Probe",
	["A Host of Evil"] = "Eine Heerschar des Bösen",
	["A Reliquary of Purity"] = "Ein Reliquiar der Reinheit",
	["A Searing Blade warlock; clear the cultists around him first."] = "Ein Hexenmeister der Sengenden Klinge. Besiegt zuerst die Kultisten um ihn herum.",
	["A Shred of Hope"] = "Ein Funken Hoffnung",
	["A Sign of Hope"] = "Ein Zeichen der Hoffnung",
	["A Stone Rumbler fights at his side; interrupt his Lightning Bolt."] = "Ein Steingrollen kämpft an seiner Seite; unterbrecht seinen Blitzschlag.",
	["A Stone Rumbler stands with him and fights at his side."] = "Ein Steingrollen steht bei ihm und kämpft an seiner Seite.",
	["A Taste of Flame"] = "Ein Vorgeschmack der Flamme",
	["A Titan dig site above Whelgar's Excavation, caught out of time, where the Titans' constructs answer to no one now. Inside: the Lost Marsh, Stalker's Thicket, the Site of the Guardian and the Lost Dig Site."] = "Eine Grabungsstätte der Titanen oberhalb von Whelgars Ausgrabungsstätte, aus der Zeit gefallen, wo die Konstrukte der Titanen niemandem mehr gehorchen. Im Inneren: die Verlorene Marsch, das Pirscherdickicht, die Stätte des Wächters und die Verlorene Grabungsstätte.",
	["A Titan vault buried under the Badlands, where Dark Iron dwarves and troggs dig for the secrets of the earthen, and the stone keeper Archaedas guards the deepest hall."] = "Ein Gewölbe der Titanen, tief unter dem Ödland begraben. Dunkeleisenzwerge und Troggs graben hier nach den Geheimnissen der Irdenen, und der Steinbewahrer Archaedas bewacht die tiefste Halle.",
	["A Twilight's Hammer shaman patrolling the tunnels."] = "Ein Schamane des Schattenhammers, der durch die Tunnel patrouilliert.",
	["A Vengeful Fate"] = "Ein rachsüchtiges Schicksal",
	["A dust storm hits the whole group now and then, and he slows the tank."] = "Ab und zu trifft ein Staubsturm die ganze Gruppe, und er verlangsamt den Tank.",
	["A fallen paladin who heals himself and shields himself from harm."] = "Ein gefallener Paladin, der sich selbst heilt und sich vor Schaden schützt.",
	["A felguard standing in the middle of the lava lake, and the hardest-hitting boss here."] = "Eine Teufelswache mitten im Lavasee und der Boss, der hier am härtesten zuschlägt.",
	["A giant turtle in the first great pool."] = "Eine Riesenschildkröte im ersten großen Becken.",
	["A giant turtle that will not attack first; killing him is optional."] = "Eine riesige Schildkröte, die nicht von sich aus angreift; der Kampf ist optional.",
	["A heavy blow that knocks the tank back."] = "Ein schwerer Schlag, der den Tank zurückwirft.",
	["A heavy swing at everyone in front of him. Only the tank should stand there."] = "Ein schwerer Hieb gegen alle vor ihm. Nur der Tank sollte dort stehen.",
	["A hidden boss you summon. Take the Black Tome from Archmage Arugal's table in Shadowfang Keep after his kill, and turn it into the Tome of Dalaran at the Leyline Focus, a blue crystal in a back room at Ambermill in Silverpine Forest."] = "Ein versteckter Boss, den Ihr beschwört. Nehmt nach dem Sieg über Erzmagier Arugal den Schwarzen Folianten von seinem Tisch in Burg Schattenfang. Verwandelt ihn am Leylinienfokus, einem blauen Kristall in einem Hinterzimmer in Bernsteinmühle im Silberwald, in den Folianten von Dalaran.",
	["A hidden elite you summon yourself."] = "Ein versteckter Elitegegner, den Ihr selbst beschwört.",
	["A huge violet raptor, the leader of Stalker's Thicket."] = "Ein riesiger violetter Raptor, der Anführer des Pirscherdickichts.",
	["A large health pool"] = "Viel Gesundheit",
	["A lightning bolt that jumps to a second player. Interrupt it."] = "Ein Blitz, der auf einen zweiten Spieler überspringt. Unterbrecht ihn.",
	["A mage or a druid can remove his Call of the Grave before it goes off. He fears, and drains two players below half health."] = "Ein Magier oder Druide kann seinen Ruf des Grabes entfernen, bevor er auslöst. Er versetzt Spieler in Furcht und entzieht unter halber Gesundheit zwei Spielern Leben.",
	["A mage trainer in a capital"] = "Ein Magierlehrer in einer Hauptstadt",
	["A magic debuff on the tank: around 65 Arcane damage every 2 seconds for 10 seconds. Dispel it."] = "Ein magischer Schwächungseffekt auf dem Tank: 10 Sekunden lang alle 2 Sekunden etwa 65 Arkanschaden. Bannt ihn.",
	["A magic dispel removes his Shadow Word: Pain."] = "Sein Schattenwort: Schmerz lässt sich als Magieeffekt bannen.",
	["A massive plant creature; optional."] = "Eine gewaltige Pflanzenkreatur; optional.",
	["A murloc chieftain in his shrine. His followers run for help when they are low on health, so finish them off."] = "Ein Murlochäuptling in seinem Schrein. Seine Anhänger laufen bei niedriger Gesundheit davon, um Hilfe zu holen. Erledigt sie also vorher.",
	["A naga sorceress in a side cavern off the pool; optional."] = "Eine Nagazauberin in einer Seitenhöhle am Becken; optional.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: Jordan's Smithing Hammer, picked up from Jordan's Hammer in the courtyard. The rest: Whitestone Oak Lumber in the Deadmines, the Kor Gem in Blackfathom Deeps and Jordan's ore shipment in Loch Modan."] = "Eine Paladinquest für Menschen und Zwerge, mit Teilen von mehreren Orten. Hier: Jordans Schmiedehammer, den Ihr bei Jordans Hammer im Hof aufhebt. Der Rest: Weißsteineichenholz in den Todesminen, der Kor-Edelstein in der Tiefschwarzen Grotte und Jordans Erzlieferung in Loch Modan.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: Whitestone Oak Lumber, which the Goblin Woodcarvers drop. The rest: Jordan's Smithing Hammer in Shadowfang Keep, the Kor Gem in Blackfathom Deeps and Jordan's ore shipment in Loch Modan."] = "Eine Paladinquest für Menschen und Zwerge, mit Teilen von mehreren Orten. Hier: Weißsteineichenholz, das die Goblinholzschnitzer fallen lassen. Der Rest: Jordans Schmiedehammer in Burg Schattenfang, der Kor-Edelstein in der Tiefschwarzen Grotte und Jordans Erzlieferung in Loch Modan.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: the Corrupted Kor Gem, from the Blackfathom Sea Witches inside or the Tide Priestesses and Oracles at the entrance in Ashenvale; Thundris Windweaver in Auberdine cleanses it. The rest: Whitestone Oak Lumber in the Deadmines, Jordan's Smithing Hammer in Shadowfang Keep and Jordan's ore shipment in Loch Modan."] = "Eine Paladinquest für Menschen und Zwerge mit Teilen aus mehreren Orten. Hier: der Verderbte Kor-Edelstein, von den Meerhexen der Tiefschwarzen Grotte im Inneren oder von den Gezeitenpriesterinnen und Orakeln am Eingang im Eschental; Thundris Windwirker in Auberdine reinigt ihn. Der Rest: Weißsteineichenholz in den Todesminen, Jordans Schmiedehammer in Burg Schattenfang und Jordans Erzlieferung in Loch Modan.",
	["A patrol"] = "Eine Patrouille",
	["A pillar of flame where a player stands (3-second cast): Fire damage, then more every 3 seconds for 9 seconds. Step out of it."] = "Eine Flammensäule unter einem Spieler (3 Sek. Zauberzeit): Feuerschaden, dann 9 Sekunden lang alle 3 Sekunden weiterer. Tretet heraus.",
	["A player takes more Physical damage for 10 minutes (2-second cast). A mage or a druid can remove it."] = "Ein Spieler erleidet 10 Minuten lang mehr körperlichen Schaden (2 Sek. Zauberzeit). Ein Magier oder Druide kann den Fluch entfernen.",
	["A priest or a shaman can remove his Bloodlust."] = "Ein Priester oder Schamane kann seinen Kampfrausch entfernen.",
	["A quilboar geomancer close to the Kraul's entrance."] = "Ein Geomant der Stacheleber nahe dem Eingang des Krals.",
	["A raid new in WoW: Forever, on Mount Hyjal. Its bosses and loot are not known yet."] = "Ein neuer Schlachtzug in WoW: Forever, auf dem Berg Hyjal. Seine Bosse und Beute sind noch nicht bekannt.",
	["A raid new in WoW: Forever. Its bosses and loot are not known yet."] = "Ein neuer Schlachtzug in WoW: Forever. Seine Bosse und Beute sind noch nicht bekannt.",
	["A rare bat in a small recess of the bat cave near Charlga Razorflank: not every run meets it."] = "Eine seltene Fledermaus in einer kleinen Nische der Fledermaushöhle nahe Charlga Klingenflanke: Nicht jeder Durchlauf trifft auf sie.",
	["A rare bat, not there on every run. When it is, it waits in a small recess in the wall of the bat cave near Charlga Razorflank."] = "Eine seltene Fledermaus, die nicht bei jedem Durchlauf erscheint. Ist sie da, wartet sie in einer kleinen Nische in der Wand der Fledermaushöhle nahe Charlga Klingenflanke.",
	["A rare spawn: not every run meets him."] = "Ein seltener Gegner: Nicht in jedem Durchlauf trefft Ihr auf ihn.",
	["A rare spawn: not every run meets him. At 15% health he runs for help."] = "Ein seltener Gegner: Nicht in jedem Durchlauf trefft Ihr auf ihn. Bei 15% Gesundheit flieht er, um Hilfe zu holen.",
	["A rare. A Stone Rumbler fights with him; interrupt his Lightning Bolt, and finish him before he runs for help at 15% health."] = "Ein seltener Gegner. Ein Steingrollen kämpft an seiner Seite. Unterbrecht seinen Blitzschlag und erledigt ihn, bevor er bei 15% Gesundheit um Hilfe flieht.",
	["A rare. He calls two Burning Servants; interrupt his Fireball, and a priest or a shaman can remove his fire shield."] = "Ein seltener Gegner. Er ruft zwei Brennende Diener herbei; unterbrecht seinen Feuerball. Ein Priester oder Schamane kann seinen Feuerschild entfernen.",
	["A rare. He cuts the tank's armour by three quarters, and at 15% health runs for help: finish him first."] = "Ein seltener Gegner. Er senkt die Rüstung des Tanks um drei Viertel und flieht bei 15% Gesundheit, um Hilfe zu holen: Erledigt ihn zuerst.",
	["A satyr on the walkway above Jergosh's chamber."] = "Ein Satyr auf dem Steg über Jergoshs Kammer.",
	["A slow heal (3.5 seconds) on himself or an ally. Interrupt it."] = "Eine langsame Heilung (3.5 Sekunden) auf sich selbst oder einen Verbündeten. Unterbrecht sie.",
	["A storm of dust that hits the group for about 160 to 330 nature damage. Healers, be ready for it."] = "Ein Staubsturm, der der Gruppe etwa 160 bis 330 Naturschaden zufügt. Heiler, seid darauf vorbereitet.",
	["A test of the tank: he hits hard, disarms, and his Unholy Frenzy speeds his attacks by 75% for 20 seconds. Purge or dispel the frenzy, and tanks should bring a shield."] = "Eine Prüfung für den Tank: Er schlägt hart zu, entwaffnet, und seine Unheilige Raserei erhöht sein Angriffstempo 20 Sekunden lang um 75%. Reinigt oder bannt die Raserei. Tanks sollten einen Schild mitbringen.",
	["A threshadon in the underwater cave; optional. He only melees."] = "Ein Dreschadon in der Unterwasserhöhle; optional. Er greift nur im Nahkampf an.",
	["A thunder lizard in the water; killing him is optional."] = "Eine Donnerechse im Wasser; der Kampf ist optional.",
	["A titan site hidden in Un'Goro Crater, guarding secrets of the makers among the crater's dinosaurs."] = "Eine im Krater von Un'Goro verborgene Titanenstätte, die inmitten der Dinosaurier des Kraters die Geheimnisse der Schöpfer hütet.",
	["A treant twisted by fel magic, among the Suffused Treants in the streets."] = "Ein von Teufelsmagie verderbter Treant, inmitten der Durchtränkten Treants in den Straßen.",
	["A trogg brute on the main path; a straightforward fight if no other packs join in."] = "Ein grobschlächtiger Trogg auf dem Hauptweg. Ein einfacher Kampf, solange keine weiteren Gegnergruppen dazukommen.",
	["A troll city that sank into the ocean long ago has risen again, and naga, pirates and stranger things from the deep have claimed its streets."] = "Eine Trollstadt, die vor langer Zeit im Meer versank, ist wieder aufgestiegen, und Naga, Piraten und noch seltsamere Wesen aus der Tiefe haben ihre Straßen erobert.",
	["A vast cavern under Desolace, sacred to the centaur, where Princess Theradras, daughter of Therazane, has fouled the waters and the resting place of Zaetar."] = "Eine gewaltige Höhle unter Desolace, den Zentauren heilig. Prinzessin Theradras, Tochter von Therazane, hat hier die Gewässer und die Ruhestätte von Zaetar verunreinigt.",
	["A ward closes his cave. Kill the two Death's Head Ward Keepers standing in front of it: the ward goes down when both are dead."] = "Ein Schutzzauber versperrt seine Höhle. Tötet die beiden Schutzwächter des Totenkopfs, die davor stehen: Der Schutzzauber fällt, sobald beide tot sind.",
	["A ward seals his cave: kill the two Death's Head Ward Keepers in front of it to bring it down."] = "Ein Schutzzauber versiegelt seine Höhle: Tötet die beiden Schutzwächter des Totenkopfs davor, um ihn zu brechen.",
	["A warlock quest. The fragments come from here and from Blackfathom Deeps."] = "Eine Hexenmeisterquest. Die Fragmente stammen von hier und aus der Tiefschwarzen Grotte.",
	["A way to remove a curse or cure a disease comes in handy. Otherwise an easy fight: clear the room before the pull."] = "Eine Möglichkeit, Flüche zu entfernen oder Krankheiten zu heilen, ist nützlich. Ansonsten ein leichter Kampf: Säubert den Raum, bevor Ihr den Boss angreift.",
	["A white crocolisk of the marsh."] = "Ein weißer Krokilisk der Marsch.",
	["Abandoned Hope"] = "Verlorene Hoffnung",
	["Abominable Creatures"] = "Abscheuliche Kreaturen",
	["Abominable Head"] = "Abscheulicher Kopf",
	["About every 20 seconds he fears up to three players near him: a shaman's Tremor Totem helps. Late in the fight he enrages."] = "Etwa alle 20 Sekunden versetzt er bis zu drei Spieler in seiner Nähe in Furcht: Das Totem des Erdstoßes eines Schamanen hilft. Spät im Kampf bekommt er einen Wutanfall.",
	["About every 20 seconds he roars and fears up to three players near him. A shaman's Tremor Totem helps."] = "Etwa alle 20 Sekunden brüllt er und versetzt bis zu drei Spieler in seiner Nähe in Furcht. Das Totem des Erdstoßes eines Schamanen hilft.",
	["About one run in three, one of the graveyard's three rares stands at one of six places: Azshir the Sleepless, the Fallen Champion or Ironspine."] = "Etwa bei jedem dritten Durchlauf steht einer der drei seltenen Gegner des Friedhofs an einem von sechs Orten: Azshir der Schlaflose, der Gefallene Champion oder Eisenrücken.",
	["About one run in three, one of the graveyard's three rares stands at one of the six places on the map: Azshir the Sleepless, Fallen Champion or Ironspine."] = "Etwa bei jedem dritten Durchlauf steht einer der drei seltenen Gegner des Friedhofs an einem der sechs Orte auf der Karte: Azshir der Schlaflose, Gefallener Champion oder Eisenrücken.",
	["Above and Beyond"] = "Über die Pflicht hinaus",
	["Acid Splash hurts everyone near him over time. Interrupt his heal below half health; at 15% he runs for help."] = "Säurespritzer fügt allen in seiner Nähe Schaden über Zeit zu. Unterbrecht seine Heilung unter halber Gesundheit; bei 15% flieht er, um Hilfe zu holen.",
	["Advisor Belgrum, Dun Morogh"] = "Berater Belgrum, Dun Morogh",
	["Afadra Dunwall, Ironforge"] = "Afadra Dunwall, Eisenschmiede",
	["After 60 seconds, Shadow damage to the player (2-second cast). A mage or a druid can remove it before then."] = "Fügt dem Spieler nach 60 Sekunden Schattenschaden zu (2 Sek. Zauberzeit). Ein Magier oder Druide kann den Fluch vorher entfernen.",
	["After a 3-second cast, a beam comes out in front of it for 6 seconds and hits four times a second. Get out of its path as soon as the cast starts."] = "Nach 3 Sekunden Zauberzeit schießt 6 Sekunden lang ein Strahl nach vorn und trifft viermal pro Sekunde. Geht ihm aus dem Weg, sobald der Zauber beginnt.",
	["After the fight, open the room's vaults: about 24 Dwarven Heirlooms for Important Heirlooms, and the stone tablet that starts The Treaty of Understanding."] = "Öffnet nach dem Kampf die Gewölbe des Raums: etwa 24 Zwergische Erbstücke für „Wichtige Erbstücke“ und die Steintafel, mit der „Der Vertrag der Verständigung“ beginnt.",
	["After the fight, open the vaults of the room: about 24 Dwarven Heirlooms for Important Heirlooms, and the tablet of The Treaty of Understanding."] = "Öffnet nach dem Kampf die Gewölbe des Raums: etwa 24 Zwergische Erbstücke für „Wichtige Erbstücke“ und die Tafel für „Der Vertrag der Verständigung“.",
	["Agmond's Fate"] = "Agmonds Schicksal",
	["Aku'mai's Lair"] = "Aku'mais Hort",
	["Alba Fairmoon"] = "Alba Fairmoon",
	["Alba Fairmoon gives it at Sentinel Hill at the end of her chain, after a trip to Stormwind for ten Coarse Dynamite for Sprite Jumpsprocket. The forge is in the foundry, where Gilnid is fought; she then waits at the dungeon's exit with the detonator."] = "Alba Fairmoon vergibt sie auf der Späherkuppe am Ende ihrer Questreihe, nach einem Abstecher nach Sturmwind, wo Ihr zehnmal Grobes Dynamit für Sprite Jumpsprocket besorgt. Die Schmiede steht in der Gießerei, wo Ihr gegen Gilnid kämpft; danach wartet sie mit dem Zünder am Ausgang des Dungeons.",
	["Alba Fairmoon, Sentinel Hill, Westfall"] = "Alba Fairmoon, Späherkuppe, Westfall",
	["Alba Fairmoon, at the Deadmines' exit"] = "Alba Fairmoon, am Ausgang der Todesminen",
	["Alba Fairmoon, at the Deadmines' exit, Westfall"] = "Alba Fairmoon, am Ausgang der Todesminen, Westfall",
	["Alcaz Island, Dustwallow Marsh"] = "Insel Alcaz, Düstermarschen",
	["Alexi Barov, Tirisfal Glades"] = "Alexi Barov, Tirisfal",
	["Allegiance to the Old Gods"] = "Treue zu den Alten Göttern",
	["Also from Courier Hammerfall in Ironforge and Herald Moonstalker in Darnassus."] = "Auch bei Kurier Hammerfall in Eisenschmiede und Herold Mondpirscher in Darnassus erhältlich.",
	["Altar of Hakkar, inside the dungeon"] = "Altar von Hakkar, im Dungeon",
	["Alterac Mountains"] = "Alteracgebirge",
	["Altered Beings"] = "Veränderte Wesen",
	["Amongst the Ruins"] = "Inmitten der Ruinen",
	["Amulet of Secrets"] = "Amulett der Geheimnisse",
	["An Alarming Request"] = "Eine beunruhigende Bitte",
	["An Ambassador of Evil"] = "Ein Botschafter des Bösen",
	["An Ancient Grudge"] = "Ein uralter Groll",
	["An Unholy Alliance"] = "Eine unheilige Allianz",
	["An Unsent Letter"] = "Ein nicht abgeschickter Brief",
	["An arcane golem by the Magus Commerce Exchange, guarded by Angry Tomes. Its Malfunction hits everyone within 25 yards."] = "Ein Arkangolem bei der Magierhandelsbörse, bewacht von Wütenden Folianten. Seine Fehlfunktion trifft alle im Umkreis von 25 Metern.",
	["An escort: Grark is held at the Blackrock fortress in the Burning Steppes."] = "Eine Eskorte: Grark wird in der Schwarzfelsfestung in der Brennenden Steppe festgehalten.",
	["An ogre foreman with heavy armour who hits hard; the first boss inside."] = "Ein schwer gepanzerter Oger-Vorarbeiter, der hart zuschlägt; der erste Boss im Inneren.",
	["An ogre stronghold packed with warriors, where the Twilight's Hammer has found willing allies."] = "Eine Festung der Oger voller Krieger. Hier hat der Schattenhammer bereitwillige Verbündete gefunden.",
	["An ogre who throws lightning that jumps between players."] = "Ein Oger, der Blitze schleudert, die zwischen Spielern überspringen.",
	["An ooze soaked in radiation, in the Hall of Gears."] = "Ein von Strahlung durchtränkter Schlamm in der Halle der Zahnräder.",
	["An orb flies to a random player and comes back to him. Anyone it passes through takes Arcane damage and is silenced for 6 seconds: don't stand between him and that player."] = "Eine Kugel fliegt zu einem zufälligen Spieler und kehrt zum Boss zurück. Wen sie durchquert, erleidet Arkanschaden und wird 6 Sekunden lang zum Schweigen gebracht. Steht nicht zwischen dem Boss und diesem Spieler.",
	["Ancient Gurubashi Idol"] = "Uraltes Götzenbild der Gurubashi",
	["Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull."] = "Andrew Brownell möchte, dass Ihr Amnennar den Kältebringer tötet und seinen Schädel zurückbringt.",
	["Andrew Brownell, Undercity"] = "Andrew Brownell, Unterstadt",
	["Angry Tomes"] = "Wütende Folianten",
	["Angry Tomes come at you on the way to it. Kill them before you pull."] = "Auf dem Weg zum Boss greifen Euch Wütende Folianten an. Tötet sie vor dem Pull.",
	["Angry Tomes come out of the buildings as you approach: clear them before the fight."] = "Wenn Ihr Euch nähert, kommen Wütende Folianten aus den Gebäuden. Beseitigt sie vor dem Kampf.",
	["Anthion Harmon, Eastern Plaguelands"] = "Anthion Harmon, Östliche Pestländer",
	["Anthion's Old Friend"] = "Anthions alter Freund",
	["Anti-Magic Shield"] = "Antimagieschild",
	["Anti-Magic Shield guards him against spells for a while, and he hits hard: keep the tank topped up."] = "Antimagieschild schützt ihn eine Zeit lang vor Zaubern, und er schlägt hart zu: Haltet den Tank bei voller Gesundheit.",
	["Apothecary Zamah — Pools of Vision, Thunder Bluff"] = "Apothekerin Zamah — Teiche der Visionen, Donnerfels",
	["Apothecary Zamah, Thunder Bluff"] = "Apothekerin Zamah, Donnerfels",
