	["Bring the End"] = "Bringt das Ende",
	["Bring the Fallen Hero of the Horde voodoo feathers from the temple's troll leaders."] = "Bringt dem Gefallenen Helden der Horde Voodoofedern von den Trollanführern des Tempels.",
	["Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris."] = "Bringt die fünfte und sechste Mosh'aru-Tafel zu Prospektor Eisenstiefel in Tanaris.",
	["Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris."] = "Bringt das gefüllte Ei von Hakkar zu Yeh'kinya in Tanaris.",
