	["En-Ay-Es-Tee-Why"] = "En-Ay-Es-Tee-Why",
	["Enohar Thunderbrew, Blasted Lands"] = "Enohar Donnerbräu, Verwüstete Lande",
	["Entangle roots up to two players near him and hurts them: dispel it. Fel Timbers leaves poisonous pools: anyone rooted in one needs Blessing of Freedom or Escape Artist."] = "Umschlingen hält bis zu zwei Spieler in seiner Nähe fest und verletzt sie: Bannt es. Teufelsholz hinterlässt giftige Lachen. Wer darin festgehalten wird, braucht Segen der Freiheit oder Entfesselungskünstler.",
	["Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart."] = "Betretet die Schwarzfelstiefen und spürt Lord Incendius auf. Tötet ihn und bringt Donnerherz alles, was Euch Aufschluss geben könnte.",
	["Enter Hall of Thanes and claim Durgen Dirgehammer's Head."] = "Betretet die Halle der Thane und holt Euch Durgen Klagehammers Kopf.",
	["Enter the Excavation Sites in the Wetlands and bring back 4 Thicket Raptor Meat."] = "Betretet die Ausgrabungsstätten im Sumpfland und bringt 4 Dickichtraptorfleisch zurück.",
	["Eranikus, Tyrant of the Dream"] = "Eranikus, Tyrann des Traums",
	["Escort Belnistrasz to the Quilboar's idol in Razorfen Downs."] = "Geleitet Belnistrasz zum Götzenbild der Stacheleber im Hügel der Klingenhauer.",
	["Escort Kernobee to the Clockwerk Run exit, then report to Scooty in Booty Bay."] = "Eskortiert Kernobee zum Ausgang des Uhrwerkgangs und meldet Euch dann bei Scooty in Beutebucht.",
	["Escort Willix the Importer out of Razorfen Kraul."] = "Geleitet Willix den Importeur aus dem Kral der Klingenhauer.",
	["Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge."] = "Eskortiert Euren Gefangenen Grark Lorkrub durch die Brennende Steppe und durch den Schwarzfels in die Sengende Schlucht.",
	["Essence Font, inside the dungeon"] = "Essenzbrunnen, im Dungeon",
	["Essential Artificials"] = "Essenzielle Kunstteile",
	["Eva Sarkhoff, Western Plaguelands"] = "Eva Sarkhoff, Westliche Pestländer",
	["Every 15 to 25 seconds he spins for 10 seconds, hitting everyone near him. Melee, step back until it ends."] = "Alle 15 bis 25 Sekunden dreht er sich 10 Sekunden lang im Kreis und trifft alle in seiner Nähe. Nahkämpfer, tretet zurück, bis es vorbei ist.",
	["Every 15 to 25 seconds he whirls for 10 seconds, hitting everyone near him: melee, step back until it ends."] = "Alle 15 bis 25 Sekunden wirbelt er 10 Sekunden lang herum und trifft alle in seiner Nähe: Nahkämpfer, tretet zurück, bis es vorbei ist.",
	["Every 21 to 35 seconds he strikes a player other than his target, who falls as if dead and can neither attack nor cast. Moving ends it."] = "Alle 21 bis 35 Sekunden trifft er einen Spieler außer seinem Ziel, der wie tot zu Boden fällt und weder angreifen noch zaubern kann. Bewegung beendet den Effekt.",
	["Every 25 to 31 seconds: hits everyone near him and stuns them for 2.5 seconds."] = "Alle 25 bis 31 Sekunden: Trifft alle in seiner Nähe und betäubt sie für 2.5 Sekunden.",
	["Every 8 to 14 seconds: Nature damage to everyone near him, and their attacks and movement are slowed for 10 seconds."] = "Alle 8 bis 14 Sekunden: Naturschaden an allen in seiner Nähe, dazu 10 Sekunden lang verlangsamte Angriffe und Bewegung.",
	["Every 9 to 15 seconds she is immune to all attacks and spells for 2 seconds."] = "Alle 9 bis 15 Sekunden ist sie 2 Sekunden lang gegen alle Angriffe und Zauber immun.",
	["Every few seconds, Arcane damage to everyone within 10 yards. Ranged players, keep your distance."] = "Alle paar Sekunden Arkanschaden an allen im Umkreis von 10 Metern. Fernkämpfer, haltet Abstand.",
	["Explosive Consultation"] = "Explosive Beratung",
	["Extinguishing the Idol"] = "Das Götzenbild auslöschen",
	["Extra damage on the tank every 5 to 15 seconds."] = "Alle 5 bis 15 Sekunden zusätzlicher Schaden am Tank.",
	["Falfindel Waywarder — Thalanaar"] = "Falfindel Waywarder — Thalanaar",
	["Falfindel Waywarder, Thalanaar, Feralas"] = "Falfindel Waywarder, Thalanaar, Feralas",
	["Falla Sagewind"] = "Falla Weisenwind",
	["Falla Sagewind, The Barrens"] = "Falla Weisenwind, Brachland",
	["Fallen Hero of the Horde, Swamp of Sorrows"] = "Gefallener Held der Horde, Sümpfe des Elends",
	["Fallen in the Fen"] = "Gefallen im Moor",
	["Falrin Treeshaper, inside the dungeon"] = "Falrin Rankenweber, im Dungeon",
	["Falrin's Vendetta"] = "Falrins Vendetta",
	["Fear at low health"] = "Furcht bei niedriger Gesundheit",
	["Feathermoon Stronghold"] = "Mondfederfeste",
	["Fel'zerul, Swamp of Sorrows"] = "Fel'zerul, Sümpfe des Elends",
	["Felnok Steelspring, Winterspring"] = "Felnok Stahlfeder, Winterquell",
	["Feralas"] = "Feralas",
	["Fights in the arena of the Launch Bay."] = "Kämpft in der Arena der Startrampe.",
	["Fights with his pet Chomper in the trogg cave off the outer ring."] = "Kämpft zusammen mit seinem Haustier Chomper in der Trogghöhle abseits des äußeren Rings.",
	["Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon."] = "Füllt die überzogene himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.",
	["Fill the Coated Cerulean Vial at the orange crystal pool, pour it on the Vylestem Vines and kill the 8 Noxxious Scions that come out."] = "Füllt die überzogene himmelblaue Phiole am orangefarbenen Kristallteich, gießt sie über die Schlangenstrunkranken und tötet die 8 Noxxischen Sprösslinge, die daraus hervorkommen.",
	["Final Passage"] = "Die letzte Passage",
	["Final Preparations"] = "Letzte Vorbereitungen",
	["Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan."] = "Findet 3 Fragmente von Soran'ruk und 1 Großes Fragment von Soran'ruk und bringt sie zu Doan Karhan.",
	["Find Ardin Grassman in the Excavation Site and learn what became of him."] = "Findet Ardin Grassman in der Ausgrabungsstätte und erfahrt, was aus ihm geworden ist.",
	["Find Argent Guard Thaelrid inside Blackfathom Deeps."] = "Findet Argentumwache Thaelrid in der Tiefschwarzen Grotte.",
	["Find Baelog inside Uldaman."] = "Findet Baelog in Uldaman.",
	["Find Bijou's Belongings and return them to her. Good luck!"] = "Findet Bijous Habseligkeiten und bringt sie ihr zurück. Viel Glück!",
	["Find Commander Gor'shak in a prison cell in Blackrock Depths."] = "Findet Kommandant Gor'shak in einer Gefängniszelle in den Schwarzfelstiefen.",
	["Find Deathstalker Adamant and Deathstalker Vincent inside Shadowfang Keep."] = "Findet Todespirscher Adamant und Todespirscher Vincent in Burg Schattenfang.",
	["Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete."] = "Sucht Doktor Theolen Krastinov in der Scholomance. Vernichtet ihn und verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, wenn die Aufgabe erledigt ist.",
	["Find Drakkisath's Brand, guarded by General Drakkisath, to get the Mark of Drakkisath."] = "Findet Drakkisaths Brandzeichen, das von General Drakkisath bewacht wird, um das Mal von Drakkisath zu erhalten.",
	["Find Fras Siabi's smoke shop in Stratholme and recover a box of Siabi's Premium Tobacco. Return to Smokey LaRue when the job is done."] = "Findet Fras Siabis Tabakladen in Stratholme und beschafft eine Kiste von Siabis Premiumtabak. Kehrt zu Smokey LaRue zurück, wenn die Arbeit erledigt ist.",
	["Find Hammertoe Grez in the caves before Uldaman."] = "Findet Hammerzeh Grez in den Höhlen vor Uldaman.",
	["Find Hammertoe's Amulet and return it to him in Uldaman."] = "Findet Hammerzehs Amulett und bringt es ihm in Uldaman zurück.",
	["Find Kharan Mighthammer in the Blackrock Depths prison."] = "Findet Kharan Mächtighammer im Gefängnis der Schwarzfelstiefen.",
	["Find Lord Incendius in Blackrock Depths and destroy him!"] = "Findet Lord Incendius in den Schwarzfelstiefen und vernichtet ihn!",
	["Find Marvon Rivetseeker in Tanaris."] = "Sucht Marvon Nietensucher in Tanaris auf.",
	["Find Maur Grimtotem's corpse in Ragefire Chasm and search it."] = "Findet die Leiche von Maur Grimmtotem im Flammenschlund und durchsucht sie.",
	["Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke."] = "Sucht Ras Frostraunen in der Scholomance. Habt Ihr ihn gefunden, benutzt das seelengebundene Andenken an seiner untoten Gestalt. Gelingt es Euch, ihn wieder sterblich zu machen, streckt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduke.",
	["Find The Beginnings of the Undead Threat in the Library and bring it to Parqual Fintallas."] = "Findet „Die Anfänge der untoten Bedrohung“ in der Bibliothek und bringt es zu Parqual Fintallas.",
	["Find Treshala's Pendant and return it to Treshala Fallowbrook in Darnassus."] = "Findet Treshalas Anhänger und bringt ihn zu Treshala Fallowbrook in Darnassus.",
	["Find a way to clean the grime off the ring: the Sparklematic 5200 in Gnomeregan will."] = "Findet einen Weg, den Schmutz vom Ring zu entfernen: Der Funkelmat 5200 in Gnomeregan erledigt das.",
	["Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic."] = "Findet und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wutschnittergolems und Kriegshetzerkonstrukten sammeln, die Argelmach beschützen. Das wisst Ihr, weil Ihr hellseherische Kräfte habt.",
	["Find someone in Kargath (Badlands) who can translate the paladin's journal."] = "Findet in Kargath (Ödland) jemanden, der das Tagebuch des Paladins übersetzen kann.",
	["Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows."] = "Findet den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends.",
	["Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul."] = "Findet die Stulpen der Gordokmacht und bringt sie zu Hauptmann Krombruch in Düsterbruch.",
	["Find the Gems"] = "Die Edelsteine finden",
	["Find the Gems and Power Source"] = "Edelsteine und Energiequelle finden",
	["Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge."] = "Findet die Tafel des Willens und bringt sie zu Berater Belgrum in Eisenschmiede.",
	["Find the belongings Bijou stashed on the bottom floor of the city, and bring them back to her."] = "Findet die Habseligkeiten, die Bijou im untersten Stockwerk der Stadt versteckt hat, und bringt sie ihr zurück.",
	["Find the ruby, sapphire, and topaz that are scattered throughout Uldaman. Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you."] = "Findet den Rubin, den Saphir und den Topas, die überall in Uldaman verstreut sind. Habt Ihr sie, nehmt mit der Phiole der Weissagung, die Talvash del Kissel Euch gegeben hat, aus der Ferne Kontakt zu ihm auf.",
	["Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan."] = "Findet die drei Edelsteine der Befehlsgewalt: den Edelstein der Glutdorn, den Edelstein der Felsspitzoger und den Edelstein der Blutaxt. Bringt sie zusammen mit dem schmucklosen Siegel des Aufstiegs zu Vaelan.",
	["Finkle Einhorn, At Your Service!"] = "Finkle Einhorn, zu Euren Diensten!",
	["Fire Nova burns everyone near him several times a fight: healers, keep the melee topped up."] = "Feuernova verbrennt mehrmals pro Kampf alle in seiner Nähe: Heiler, haltet die Nahkämpfer bei voller Gesundheit.",
	["Fire all around"] = "Feuer ringsum",
	["Fire damage every 3 seconds for 15 seconds, with slower attacks and movement. Interrupt the 2-second cast."] = "15 Sekunden lang alle 3 Sekunden Feuerschaden, dazu verlangsamte Angriffe und Bewegung. Unterbrecht den Zauber (2 Sekunden Zauberzeit).",
	["Fire damage to a player, then more every 3 seconds for 12 seconds. A Magic dispel removes it."] = "Feuerschaden an einem Spieler, dann 12 Sekunden lang alle 3 Sekunden weiterer. Lässt sich als Magieeffekt bannen.",
	["Fire damage to everyone near him for a minute. A priest or a shaman can remove it."] = "Eine Minute lang Feuerschaden an allen in seiner Nähe. Ein Priester oder Schamane kann den Schild entfernen.",
	["Fire damage to everyone near him, several times a fight. Healers, keep the melee topped up."] = "Feuerschaden an allen in seiner Nähe, mehrmals pro Kampf. Heiler, haltet die Nahkämpfer bei voller Gesundheit.",
	["Fire damage to everyone within 10 yards of him."] = "Fügt allen im Umkreis von 10 Metern um ihn Feuerschaden zu.",
	["Fix the broken trap with a Thorium Widget and Frost Oil."] = "Repariert die kaputte Falle mit einem Thoriumapparat und Frostöl.",
	["Flamestrike"] = "Flammenstoß",
	["Flamestrike is his main spell, and he can be interrupted and stunned: plan your kicks and stuns."] = "Flammenstoß ist sein Hauptzauber, und er kann unterbrochen und betäubt werden: Plant Eure Unterbrechungen und Betäubungen.",
	["Focal Blast: after a 3-second cast, a beam sweeps around the room, turning counterclockwise, for 6 seconds. Get out of its path as the cast starts: it kills."] = "Fokussierte Explosion: Nach 3 Sekunden Zauberzeit fegt 6 Sekunden lang ein Strahl gegen den Uhrzeigersinn durch den Raum. Geht ihm aus dem Weg, sobald der Zauber beginnt: Er ist tödlich.",
	["Follow the quest directions beginning in Ratchet"] = "Folgt den Anweisungen der Quest, beginnend in Ratschet",
	["Follows Badlands Reagent Run."] = "Folgt auf „Reagenzien aus dem Ödland“.",
	["Follows Going, Going, Guano! The Scarlet Crusaders of every wing carry the hearts, and so do their leaders."] = "Folgt auf „Zum Ersten, zum Zweiten, Guano!“. Die Scharlachroten Kreuzritter aller Flügel tragen die Herzen bei sich, ebenso ihre Anführer.",
	["Follows Journey to the Marsh. The book lies at the north end of the hallway to Arcanist Doan."] = "Folgt auf „Reise in die Marschen“. Das Buch liegt am Nordende des Gangs zu Arkanist Doan.",
	["Follows Operative Bijou."] = "Folgt auf „Agentin Bijou“.",
	["Follows Seeking Caitlin, from Llana in Ashenvale; leads to Heartwoven."] = "Folgt auf „Auf der Suche nach Caitlin“ von Llana im Eschental und führt zu „Herzgewoben“.",
	["Follows The Madness Within."] = "Folgt auf „Der Wahnsinn im Inneren“.",
	["For 12 seconds he takes 60% less damage, and attacks slower but harder."] = "12 Sekunden lang erleidet er 60% weniger Schaden und greift langsamer, aber härter an.",
	["For The Horde!"] = "Für die Horde!",
	["For blacksmiths with a skill of 250."] = "Für Schmiede mit einer Fertigkeit von 250.",
	["Forest Wisp, Teldrassil"] = "Waldirrwisch, Teldrassil",
	["Forever's quest data also lists Arcane Intellect among the spells it teaches."] = "Laut den Questdaten von Forever gehört auch Arkane Intelligenz zu den Zaubern, die sie lehrt.",
	["Forging the Mightstone"] = "Das Schmieden des Machtsteins",
	["Forlorn Cloister"] = "Verlassener Kreuzgang",
	["Foror's Compendium"] = "Forors Kompendium",
	["Found in the graveyard inside Ruins of Lordaeron"] = "Liegt auf dem Friedhof in den Ruinen von Lordaeron",
	["Four come once Fenrus the Devourer dies, called by Arugal. They heal each other: bring them down one at a time."] = "Sobald Fenrus der Verschlinger stirbt, ruft Arugal vier von ihnen herbei. Sie heilen sich gegenseitig: Erledigt sie einen nach dem anderen.",
	["Four of them come after Fenrus the Devourer dies: Arugal appears for a moment and calls them."] = "Vier von ihnen erscheinen, nachdem Fenrus der Verschlinger gestorben ist: Arugal zeigt sich kurz und ruft sie herbei.",
	["Franclorn Forgewright, Burning Steppes"] = "Franclorn Schmiedewerk, Brennende Steppe",
	["Free Knot!"] = "Befreit Knot!",
	["Freezes everyone near her in place for up to 8 seconds."] = "Friert alle in ihrer Nähe bis zu 8 Sekunden lang an Ort und Stelle ein.",
	["Frost Nova"] = "Frostnova",
	["Frost Nova hits the whole group: healers, pace your mana through the waves."] = "Frostnova trifft die ganze Gruppe: Heiler, teilt Euer Mana über die Wellen hinweg ein.",
	["Frost Shock and You"] = "Frostschock und Du",
	["Frost damage to the whole group. Healers, pace your mana through the waves."] = "Frostschaden an der ganzen Gruppe. Heiler, teilt Euer Mana über die Wellen hinweg ein.",
	["Gahz'rilla"] = "Gahz'rilla",
	["Galamav the Marksman, Badlands"] = "Galamav der Schütze, Ödland",
	["Garona: A Study on Stealth and Treachery"] = "Garona: Eine Studie über Heimlichkeit und Verrat",
	["Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind."] = "Sammelt 10 Tafeln der Atal'ai für Brohann Fassbauch in Sturmwind.",
	["Gaxim Rustfizzle, Stonetalon Mountains"] = "Gaxim Rustfizzle, Steinkrallengebirge",
	["General Drakkisath's Command"] = "General Drakkisaths Befehl",
	["General Drakkisath's Demise"] = "General Drakkisaths Untergang",
	["General Marcus Jonathan, Stormwind City"] = "General Marcus Jonathan, Sturmwind",
	["Gerrig Bonegrip"] = "Gerrig Knochengriff",
	["Gerrig Bonegrip, Forlorn Cavern, Ironforge"] = "Gerrig Knochengriff, Die Verlassene Höhle, Eisenschmiede",
	["Gerrig Bonegrip, Forlorn Cavern, Ironforge (50.8, 5.6)"] = "Gerrig Knochengriff, Die Verlassene Höhle, Eisenschmiede (50.8, 5.6)",
	["Gershala Nightwhisper"] = "Gershala Nachtraunen",
	["Gershala Nightwhisper, Auberdine, Darkshore"] = "Gershala Nachtraunen, Auberdine, Dunkelküste",
	["Gershala Nightwhisper, Auberdine, Darkshore (38.3, 43.1)"] = "Gershala Nachtraunen, Auberdine, Dunkelküste (38.3, 43.1)",
	["Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge."] = "Holt Krom Starkarms wertvollsten Besitz aus seiner Truhe in der nördlichen Gemeinschaftshalle von Uldaman und bringt ihn zu ihm nach Eisenschmiede.",
	["Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity."] = "Holt den Familienschatz von Patrick Garrett aus der Familientruhe in der südlichen Gemeinschaftshalle von Uldaman und bringt ihn zu ihm nach Unterstadt.",
	["Get the Medallion of Faith from Malor's Strongbox and bring it to Aurius."] = "Holt das Medaillon des Glaubens aus Malors Geldkassette und bringt es zu Aurius.",
	["Ghak Healtouch, Loch Modan"] = "Ghak Heilhand, Loch Modan",
	["Ghostly Attendant, inside Hall of Thanes, after the first room"] = "Geisterhafter Diener, in der Halle der Thane, nach dem ersten Raum",
	["Ghostly Attendant, inside the dungeon"] = "Geisterhafter Diener, im Dungeon",
	["Give Marshal Maxwell the bad news."] = "Überbringt Marschall Maxwell die schlechte Nachricht.",
	["Give the Dull and Flat Elven Blade to Lorekeeper Lydros."] = "Gebt Wissenshüter Lydros die stumpfe und glanzlose Elfenklinge.",
	["Give the Sparklematic 5200 another Grime-Encrusted Object to get a Sparklematic-Wrapped Box."] = "Gebt dem Funkelmat 5200 einen weiteren Schmutzverkrusteten Gegenstand, um einen Funkelmatverpackten Kasten zu erhalten.",
	["Given by Jennea Cannon (Stormwind), Bink (Ironforge), Deino (Orgrimmar), Ursyn Ghull (Thunder Bluff) and Anastasia Hartwell (Undercity)."] = "Erhältlich bei Jennea Haubitz (Sturmwind), Bink (Eisenschmiede), Deino (Orgrimmar), Ursyn Ghull (Donnerfels) und Anastasia Hirschbrunn (Unterstadt).",
	["Glowing Shard"] = "Glühender Splitter",
	["Gnoarn, Ironforge"] = "Gnoarn, Eisenschmiede",
	["Gnogaine"] = "Gnogaine",
	["Gnome Improvement"] = "Gnomische Verbesserungen",
	["Gnomer-gooooone!"] = "Gnomer-weeeeg!",
	["Gnomeregan, the gnomes' capital beneath Dun Morogh, fell when troggs swarmed up from the deep and the gnomes flooded the city with radiation to stop them. Most of its people died; the traitor Mekgineer Thermaplugg now rules the irradiated halls with leper gnomes, troggs and his machines."] = "Gnomeregan, die Hauptstadt der Gnome unter Dun Morogh, fiel, als Troggs aus der Tiefe heraufströmten und die Gnome die Stadt mit Strahlung fluteten, um sie aufzuhalten. Die meisten Bewohner starben; der Verräter Robogenieur Thermaplugg herrscht nun mit Lepragnomen, Troggs und seinen Maschinen über die verstrahlten Hallen.",
	["Go back to the Athenaeum, find the Treasure of the Shen'dralar and claim your reward."] = "Kehrt ins Athenaeum zurück, findet den Schatz der Shen'dralar und holt Euch Eure Belohnung.",
	["Go into Blackrock Depths and find out what happened to Marshal Windsor."] = "Begebt Euch in die Schwarzfelstiefen und findet heraus, was mit Marschall Windsor geschehen ist.",
	["Go into Blackrock Spire and find out what happened to Bijou."] = "Begebt Euch in die Schwarzfelsspitze und findet heraus, was mit Bijou geschehen ist.",
	["Go into Stratholme and rescue Ysida Harmon from Baron Rivendare."] = "Geht nach Stratholme und rettet Ysida Harmon vor Baron Totenschwur.",
	["Go to Teldrassil and find Malfurion's agent outside Darnassus."] = "Reist nach Teldrassil und sucht Malfurions Gesandten vor Darnassus.",
	["Go to Thunder Bluff and talk to Arch Druid Hamuul Runetotem."] = "Reist nach Donnerfels und sprecht mit Erzdruide Hamuul Runentotem.",
	["Goblin Foundry"] = "Goblingießerei",
	["Going, Going, Guano!"] = "Zum Ersten, zum Zweiten, Guano!",
	["Grark Lorkrub"] = "Grark Lorkrub",
	["Grark Lorkrub, Burning Steppes"] = "Grark Lorkrub, Brennende Steppe",
	["Greta Mosshoof, Felwood"] = "Greta Moosehuf, Teufelswald",
	["Grime-Encrusted Ring"] = "Schmutzverkrusteter Ring",
	["Grimtotem Satchel, taken from Maur Grimtotem's corpse inside Ragefire Chasm"] = "Ranzen der Grimmtotem, von der Leiche von Maur Grimmtotem im Flammenschlund",
	["Grom'gol Base Camp"] = "Basislager von Grom'gol",
	["Gryan Stoutmantle"] = "Gryan Starkmantel",
	["Gryan Stoutmantle, Sentinel Hill tower, Westfall (56.4, 47.5)"] = "Gryan Starkmantel, Turm der Späherkuppe, Westfall (56.4, 47.5)",
	["Gryan Stoutmantle, Sentinel Hill, Westfall"] = "Gryan Starkmantel, Späherkuppe, Westfall",
	["Guard Berton — Lakeshire"] = "Wache Berton — Seenhain",
	["Guard Berton, Lakeshire, Redridge Mountains"] = "Wache Berton, Seenhain, Rotkammgebirge",
	["Guard the Disciple through waves of serpents and then oozes; Mutanus surfaces right after the oozes."] = "Beschützt den Jünger vor Wellen von Schlangen und danach von Schlammwesen; direkt nach den Schlammwesen taucht Mutanus auf.",
	["Gyrodrillmatic Excavationators"] = "Gyrobohrmatische Exkavatoren",
	["Haleh, Winterspring"] = "Haleh, Winterquell",
	["Hammertoe Grez, Loch Modan"] = "Hammerzeh Grez, Loch Modan",
	["Hamuul Runetotem"] = "Hamuul Runentotem",
	["Hand the Sparklematic 5200 a Grime-Encrusted Object for a Sparklematic-Wrapped Box."] = "Gebt dem Funkelmat 5200 einen Schmutzverkrusteten Gegenstand und erhaltet einen Funkelmatverpackten Kasten.",
	["Harnessing Shadows"] = "Schatten einspannen",
	["He calls everything within 15 yards, his two Razorfen Spearhides among them: crowd-control one. Thunderclap every 8 to 14 seconds slows those near him."] = "Er ruft alles im Umkreis von 15 Metern herbei, darunter seine beiden Speerträger der Klingenhauer: Setzt einen davon außer Gefecht. Sein Donnerknall verlangsamt alle 8 bis 14 Sekunden alle in seiner Nähe.",
	["He can be at one of four places. A priest or a shaman can remove his Lightning Shield; interrupt his Lightning Bolt."] = "Er kann an einem von vier Orten stehen. Ein Priester oder Schamane kann seinen Blitzschlagschild entfernen; unterbrecht seinen Blitzschlag.",
	["He cleaves, and at 30% health enrages for 2 minutes: much faster and harder blows."] = "Er setzt Spalten ein und gerät bei 30% Gesundheit für 2 Minuten in Raserei: viel schnellere und härtere Schläge.",
	["He cleaves, and slows his target."] = "Er spaltet und verlangsamt sein Ziel.",
	["He cleaves, and strikes hard at a target below 20% health: keep the tank above it."] = "Er setzt Spalten ein und schlägt hart auf Ziele unter 20% Gesundheit zu: Haltet den Tank darüber.",
	["He disarms the tank."] = "Er entwaffnet den Tank.",
	["He drains mana from his target: a tank who uses mana feels it."] = "Er entzieht seinem Ziel Mana: Ein Tank, der Mana nutzt, spürt das.",
	["He hits hard: keep the tank healthy. Bring mana potions for the waves before him."] = "Er schlägt hart zu: Haltet den Tank am Leben. Bringt Manatränke für die Wellen vor ihm mit.",
	["He hits hard: keep the tank topped up."] = "Er schlägt hart zu: Haltet den Tank bei voller Gesundheit.",
	["He hurls the tank into the air, stunned for 5 seconds: damage dealers, watch your threat, the tank holds him only about half the fight."] = "Er schleudert den Tank in die Luft und betäubt ihn 5 Sekunden lang: Schadensverursacher, achtet auf Eure Bedrohung, der Tank hält ihn nur etwa die Hälfte des Kampfes.",
	["He keeps calling Arcane Manalings: cleave them down."] = "Er ruft immer wieder Arkane Manalinge herbei: Erledigt sie mit Flächenangriffen.",
	["He keeps his distance to cast it. Interrupt it."] = "Er hält dafür Abstand. Unterbrecht den Zauber.",
	["He keeps his distance to cast it: Frost damage and a slow."] = "Er hält Abstand, um ihn zu wirken: Frostschaden und Verlangsamung.",
	["He knocks players across the room: clear the packs nearest him, and tank him by the tunnel so nobody lands in another pack."] = "Er schleudert Spieler quer durch den Raum: Säubert die Gegnergruppen in seiner Nähe und tankt ihn am Tunnel, damit niemand in einer anderen Gruppe landet.",
	["He knocks players back: clear the packs around him first, or you land in one."] = "Er stößt Spieler zurück: Säubert zuerst die Gegnergruppen um ihn herum, sonst landet Ihr in einer davon.",
	["He knocks the tank back and turns to someone else: he drops his threat. Damage dealers, slow down when the tank loses him. Tank, take him back at once."] = "Er schlägt den Tank zurück und wendet sich jemand anderem zu, denn die Bedrohung des Tanks sinkt. Schadensverursacher, macht langsamer, wenn der Tank ihn verliert. Tank, holt ihn Euch sofort zurück.",
	["He leaves a player for dead (moving ends it), stuns everyone near him, and enrages at 60% and again at 40% health."] = "Er überlässt einen Spieler dem Tode (Bewegung beendet es), betäubt alle in seiner Nähe und gerät bei 60% und erneut bei 40% Gesundheit in Raserei.",
	["He lies on the floor of the small room beside the altar, as if dead, and gets up when attacked."] = "Er liegt wie tot auf dem Boden des kleinen Raums neben dem Altar und steht auf, wenn er angegriffen wird.",
	["He lies on the floor of the small room beside the altar, as if dead, and rises when attacked."] = "Er liegt wie tot auf dem Boden des kleinen Raums neben dem Altar und erhebt sich, wenn er angegriffen wird.",
	["He makes the tank bleed."] = "Er lässt den Tank bluten.",
	["He nets a player in place."] = "Er hält einen Spieler mit einem Netz fest.",
	["He pilots Sneed's Shredder and climbs out when it is destroyed."] = "Er steuert Sneeds Schredder und steigt aus, wenn dieser zerstört wird.",
	["He poisons his target and hits hard. Bring mana potions for the waves before him."] = "Er vergiftet sein Ziel und schlägt hart zu. Bringt Manatränke für die Wellen vor ihm mit.",
	["He punts people around the room. Clear the packs closest to him and tank him near the tunnel, so nobody lands in another pack."] = "Er schleudert Spieler durch den Raum. Säubert die Gegnergruppen, die ihm am nächsten sind, und tankt ihn nahe dem Tunnel, damit niemand in einer anderen Gruppe landet.",
	["He puts everyone near him to sleep (damage wakes a sleeper), and casts Mind Blast."] = "Er schläfert alle in seiner Nähe ein (Schaden weckt Schlafende) und wirkt Gedankenschlag.",
	["He roams the marsh at the start among elite crocolisks, so clear them first or pull him away from them."] = "Er streift am Anfang zwischen Elite-Krokilisken durch die Marsch, also besiegt sie zuerst oder lockt ihn von ihnen weg.",
	["He roams the marsh near the start among elite crocolisks: clear them first, or pull him away from them."] = "Er streift nahe dem Eingang zwischen Elite-Krokilisken durch die Marsch: Besiegt sie zuerst oder lockt ihn von ihnen weg.",
	["He roots players in place. A paladin's Blessing of Freedom frees them."] = "Er wurzelt Spieler fest. Der Segen der Freiheit eines Paladins befreit sie.",
	["He speeds up his attacks by 75% for 20 seconds. It is magic: a shaman's Purge or a priest's Dispel Magic takes it off him."] = "Er erhöht sein Angriffstempo 20 Sekunden lang um 75%. Der Effekt ist magisch: Reinigen (Schamane) oder Magiebannung (Priester) entfernt ihn.",
	["He stands at a ritual circle in the sewers, with Kirin Tor Necromancers around him."] = "Er steht an einem Ritualkreis in der Kanalisation, umgeben von Nekromanten der Kirin Tor.",
	["He stands in a Dragonmaw camp. Its groups pull apart easily: take them one at a time first. The fight itself is short."] = "Er steht in einem Lager des Drachenmals. Dessen Gruppen lassen sich leicht einzeln anlocken: Erledigt sie zuerst nacheinander. Der Kampf selbst ist kurz.",
	["He stands still at the end of the spider trail. Click the small panel next to him to wake him."] = "Er steht reglos am Ende des Spinnenpfads. Klickt auf die kleine Konsole neben ihm, um ihn zu wecken.",
	["He stomps again and takes up his hammer."] = "Er stampft erneut auf und greift zu seinem Hammer.",
	["He stomps, stunning everyone near him, and takes up two axes."] = "Er stampft auf, betäubt alle in seiner Nähe und greift zu zwei Äxten.",
	["He summons a Boar Spirit every 30 to 45 seconds: kill each before the next comes. Below 75% health, interrupt his Chain Heal."] = "Er beschwört alle 30 bis 45 Sekunden einen Ebergeist: Tötet jeden, bevor der nächste kommt. Unterbrecht unter 75% Gesundheit seine Kettenheilung.",
	["He switches on the gnome faces around the room one by one, and each sends out Walking Bombs that explode when they reach a player. The button next to a face switches it off. Below half health he switches them on faster."] = "Er schaltet die Gnomengesichter im Raum nacheinander ein, und jedes schickt Wandelnde Bomben los, die explodieren, sobald sie einen Spieler erreichen. Der Knopf neben einem Gesicht schaltet es ab. Unter halber Gesundheit schaltet er sie schneller ein.",
	["He switches on the gnome faces around the room one by one, each sending out Walking Bombs: press the button beside a face to switch it off."] = "Er schaltet die Gnomengesichter im Raum nacheinander ein, und jedes schickt Wandelnde Bomben los: Drückt den Knopf neben einem Gesicht, um es abzuschalten.",
	["He takes the tank's weapon away for about 6 seconds."] = "Er nimmt dem Tank etwa 6 Sekunden lang die Waffe ab.",
	["He tears at the tank's legs, slowing them."] = "Er reißt an den Beinen des Tanks und verlangsamt ihn.",
	["He teleports between his ledge, the upper ledge and the stairs."] = "Er teleportiert sich zwischen seinem Vorsprung, dem oberen Vorsprung und der Treppe hin und her.",
	["He tramples everyone standing close."] = "Er trampelt alle nieder, die nah bei ihm stehen.",
	["He tramples the players next to him for about 100 physical damage."] = "Er trampelt die Spieler neben sich nieder und verursacht etwa 100 körperlichen Schaden.",
	["He waits behind a barrier in the middle of the city. Kill the Suffused Treants in front of it, then speak to Magus Fansy Goodbringer, just south of the barrier, to bring it down."] = "Er wartet hinter einer Barriere in der Stadtmitte. Tötet die Durchtränkten Treants davor und sprecht dann mit Magus Fansy Goodbringer gleich südlich der Barriere, um sie aufzuheben.",
	["He waits behind a magic barrier in the middle of the city, with Suffused Treants in front of it. Kill the treants, then talk to Magus Fansy Goodbringer, just south of the barrier: he brings it down."] = "Er wartet hinter einer magischen Barriere in der Stadtmitte, vor der Durchtränkte Treants stehen. Tötet die Treants und sprecht dann mit Magus Fansy Goodbringer gleich südlich der Barriere: Er hebt sie auf.",
	["He waits in an underwater cave below Twilight Lord Kelris's temple, where groups often miss him. Swim under the temple to reach him."] = "Er wartet in einer Unterwasserhöhle unter dem Tempel von Zwielichtlord Kelris, wo Gruppen ihn oft übersehen. Taucht unter dem Tempel hindurch, um ihn zu erreichen.",
	["He waits in an underwater cave below Twilight Lord Kelris's temple: swim under the temple to find him."] = "Er wartet in einer Unterwasserhöhle unter dem Tempel von Zwielichtlord Kelris: Taucht unter dem Tempel hindurch, um ihn zu finden.",
	["Heals a wounded ally, or herself, over 15 seconds. A priest or a shaman can remove it."] = "Heilt einen verwundeten Verbündeten oder sich selbst über 15 Sekunden. Ein Priester oder Schamane kann den Effekt entfernen.",
	["Heals another voidwalker. Bring them down one at a time."] = "Heilt einen anderen Leerwandler. Erledigt sie einen nach dem anderen.",
	["Heals herself or an ally. Interrupt it."] = "Heilt sich selbst oder einen Verbündeten. Unterbrecht den Zauber.",
	["Heals himself or an ally (2.5-second cast). Interrupt it."] = "Heilt sich selbst oder einen Verbündeten (2.5 Sekunden Zauberzeit). Unterbrecht den Zauber.",
	["Heals himself or an ally (3-second cast). Interrupt it."] = "Heilt sich selbst oder einen Verbündeten (3 Sekunden Zauberzeit). Unterbrecht den Zauber.",
	["Heals himself or an ally. Interrupt it."] = "Heilt sich selbst oder einen Verbündeten. Unterbrecht den Zauber.",
	["Heals the most wounded of her allies, Mograine included (3-second cast). Interrupt it."] = "Heilt den am schwersten verwundeten ihrer Verbündeten, auch Mograine (3 Sek. Zauberzeit). Unterbrecht den Zauber.",
	["Healthy Dragon Scale"] = "Gesunde Drachenschuppe",
	["Hear from Kharan Mighthammer about Princess Moira's kidnapping, then report to Thrall."] = "Lasst Euch von Kharan Mächtighammer von der Entführung von Prinzessin Moira berichten und erstattet dann Thrall Bericht.",
	["Heart of Disruption"] = "Herz der Störung",
	["Hearts of Zeal"] = "Herzen des Eifers",
	["Heartwoven"] = "Herzgewoben",
	["Heavy blows"] = "Schwere Schläge",
	["Helendis Riverhorn, Burning Steppes"] = "Helendis Flusshorn, Brennende Steppe",
	["Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed."] = "Helft Marschall Windsor, seine Ausrüstung zurückzubekommen und seine Freunde zu befreien. Kehrt zu Marschall Maxwell zurück, wenn Ihr Erfolg habt.",
	["Heralath Fallowbrook, inside Razorfen Kraul"] = "Heralath Fallowbrook, im Kral der Klingenhauer",
	["Hidden Enemies"] = "Verborgene Feinde",
	["High Executor Hadrec"] = "Hochexekutor Hadrec",
	["High Executor Hadrec, The Sepulcher, Silverpine Forest"] = "Hochexekutor Hadrec, Das Grabmal, Silberwald",
	["High Explorer Magellas, Dun Morogh"] = "Hochforscher Magellas, Dun Morogh",
	["High Explorer Magellas, Hall of Explorers, Ironforge"] = "Hochforscher Magellas, Halle der Forscher, Eisenschmiede",
	["High Sorcerer Andromath — Stormwind City"] = "Hochzauberer Andromath — Sturmwind",
	["High Sorcerer Andromath, Stormwind City"] = "Hochzauberer Andromath, Sturmwind",
	["High Tinker Mekkatorque — Tinker Town, Ironforge"] = "Obertüftler Mekkadrill — Tüftlerstadt, Eisenschmiede",
	["High Tinker Mekkatorque, Ironforge"] = "Obertüftler Mekkadrill, Eisenschmiede",
	["Highland Hides"] = "Hochlandhäute",
	["Highland Venom"] = "Hochlandgift",
	["His Arcane Explosion hits everyone close to him, and Detonation hits harder still: keep your distance when he readies it."] = "Seine Arkane Explosion trifft alle in seiner Nähe, und Detonation trifft noch härter: Haltet Abstand, wenn er sie vorbereitet.",
	["His Cleave also hits the player nearest his target: stand apart from the tank."] = "Sein Spalten trifft auch den Spieler, der seinem Ziel am nächsten steht: Haltet Abstand zum Tank.",
	["His Curse of Weakness reaches everyone within 30 yards (a mage or a druid can remove it), and he leaves a poison cloud."] = "Sein Fluch der Schwäche trifft alle im Umkreis von 30 Metern (ein Magier oder Druide kann ihn entfernen), und er hinterlässt eine Giftwolke.",
	["His Knock Away throws the tank back and drops his threat: damage dealers, ease off when the tank loses him; tank, take him back at once."] = "Sein Wegschlagen schleudert den Tank zurück und senkt dessen Bedrohung. Schadensverursacher, haltet Euch zurück, wenn der Tank ihn verliert. Tank, holt ihn Euch sofort zurück.",
	["His Scarlet Tracking Hounds fight beside him: kill them first. He uses Bloodlust."] = "Seine Scharlachroten Spürhunde kämpfen an seiner Seite: Tötet sie zuerst. Er setzt Kampfrausch ein.",
	["His Slam stuns the tank for 3 seconds."] = "Sein Hieb betäubt den Tank für 3 Sekunden.",
	["His Smoke Bomb stuns everyone near him; at 15% health he runs for help."] = "Seine Rauchbombe betäubt alle in seiner Nähe; bei 15% Gesundheit flieht er, um Hilfe zu holen.",
	["His Uppercut can throw a player back into lava or into nearby enemies."] = "Sein Aufwärtshaken kann einen Spieler zurück in die Lava oder zu nahen Gegnern schleudern.",
	["His blows poison: Nature damage over time. Cure it if you can."] = "Seine Schläge vergiften: Naturschaden über Zeit. Heilt das Gift, wenn Ihr könnt.",
	["His blows poison: cure it if you can. Sinister Strike adds damage on the tank."] = "Seine Schläge vergiften: Heilt das Gift, wenn Ihr könnt. Finsterer Stoß verursacht zusätzlichen Schaden am Tank.",
	["His fire hits the whole group, and harder the more of you fight in melee."] = "Sein Feuer trifft die ganze Gruppe, und zwar umso härter, je mehr von Euch im Nahkampf kämpfen.",
	["His main spell. He can be interrupted and stunned: plan your kicks and stuns."] = "Sein Hauptzauber. Er kann unterbrochen und betäubt werden: Plant Eure Unterbrechungen und Betäubungen.",
	["His room"] = "Sein Raum",
	["His shout sends nearby players fleeing in fear."] = "Sein Ruf lässt Spieler in der Nähe in Furcht fliehen.",
	["Hits everyone in a cone in front of it."] = "Trifft alle in einem Kegel vor ihm.",
	["Hits everyone near him and slows their attacks."] = "Trifft alle in seiner Nähe und verlangsamt ihre Angriffe.",
	["Hits everyone near it and interrupts their spells. Casters and healers, keep your distance."] = "Trifft alle in seiner Nähe und unterbricht ihre Zauber. Zauberwirker und Heiler, haltet Abstand.",
	["Hits everyone standing close."] = "Trifft alle, die nah bei ihm stehen.",
	["Hits his target and the player nearest to it."] = "Trifft sein Ziel und den Spieler, der ihm am nächsten steht.",
	["Hits the tank and stuns them for 2 seconds."] = "Trifft den Tank und betäubt ihn 2 Sekunden lang.",
	["Hits the tank hard and stuns them for 3 seconds."] = "Trifft den Tank hart und betäubt ihn für 3 Sekunden.",
	["Holds the top of the ship with two of his crew."] = "Hält mit zwei Männern seiner Mannschaft das Oberdeck des Schiffs.",
	["Holy Bologna: What the Light Won't Tell You"] = "Heiliger Fleischklops: Was das Licht Dir nicht erzählt",
	["Holy damage to her target (2.5-second cast). Interrupt it."] = "Heiligschaden an ihrem Ziel (2.5 Sek. Zauberzeit). Unterbrecht den Zauber.",
	["Holy damage to whoever strikes him in melee."] = "Heiligschaden an jedem, der ihn im Nahkampf trifft.",
	["Honor's Tomb"] = "Grabmal der Ehre",
	["Horrors in the Highland"] = "Schrecken im Hochland",
	["Houses of the Holy"] = "Häuser der Heiligen",
	["Huntsman's Cloister"] = "Kreuzgang des Jägers",
	["Hurled into the air"] = "In die Luft geschleudert",
	["Hurley Blackbreath"] = "Hurley Schwarzatem",
	["I See Alcaz Island In Your Future..."] = "Ich sehe die Insel Alcaz in Eurer Zukunft...",
	["Idol of Hakkar, inside the dungeon"] = "Götze von Hakkar, im Dungeon",
	["If someone leaves the room during the fight, he resets to full health."] = "Verlässt jemand während des Kampfes den Raum, setzt er sich mit voller Gesundheit zurück.",
	["If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him."] = "Wenn Ihr Belnistrasz helfen wollt, sprecht erneut mit ihm und gebt ihm den Schwurstein zurück, den er Euch gegeben hat.",
	["Image of Archmage Modera — Lordamere Lake"] = "Abbild der Erzmagierin Modera — Lordamere-See",
	["Image of Archmage Modera — Lordamere Lake near Dalaran"] = "Abbild der Erzmagierin Modera — Lordamere-See bei Dalaran",
	["Image of Archmage Modera, Lordamere Lake near Dalaran"] = "Abbild der Erzmagierin Modera, Lordamere-See bei Dalaran",
	["Important Heirlooms"] = "Wichtige Erbstücke",
	["Impsy, Felwood"] = "Impsy, Teufelswald",
	["In Gnomeregan, once the ring is clean."] = "In Gnomeregan, sobald der Ring sauber ist.",
	["In Nightmares"] = "In Albträumen",
	["In Search of Thaelrid"] = "Auf der Suche nach Thaelrid",
	["In the Chamber of Atonement. He drops Vorrel's Wedding Ring, for Vorrel's Revenge."] = "In der Kammer der Sühne. Er hinterlässt Vorrels Ehering für „Vorrels Rache“.",
	["In the Engineering Labs. He drops the Workshop Key."] = "In den Ingenieurslaboren. Er hinterlässt den Werkstattschlüssel.",
	["In the Huntsman's Cloister."] = "Im Kreuzgang des Jägers.",
	["In the Name of the Light"] = "Im Namen des Lichts",
	["In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you."] = "Im Herzen der Schwarzfelsspitze findet Ihr Mutter Glimmernetz. Greift sie an und sorgt dafür, dass sie Euch vergiftet. Wahrscheinlich müsst Ihr sie dabei auch töten. Kehrt vergiftet zum Zerlumpten John zurück, damit er Euch „melken“ kann.",
	["In the thorny barrows of the southern Barrens the Scourge has struck a pact with the quilboar: Amnennar the Coldbringer rules the Razorfen's burial grounds."] = "In den dornigen Hügelgräbern des südlichen Brachlands hat die Geißel einen Pakt mit den Stachelebern geschlossen: Amnennar der Kältebringer herrscht über die Grabstätten der Klingenhauer.",
	["Incendius!"] = "Incendius!",
	["Infected Wound"] = "Infizierte Wunde",
	["Insert a Grime-Encrusted Object into the Sparklematic 5200, with three silver coins to start the machine."] = "Legt einen Schmutzverkrusteten Gegenstand in den Funkelmat 5200, dazu drei Silbermünzen, um die Maschine zu starten.",
	["Inside a vault in the Reliquary of Kings (Durgen Dirgehammer's room)"] = "In einem Gewölbe im Reliquiar der Könige (Durgen Klagehammers Raum)",
	["Interrupt her Chain Bolt. Every so often she is immune for 2 seconds, and a priest or a shaman can remove her Renew."] = "Unterbrecht ihren Kettenblitz. Hin und wieder ist sie 2 Sekunden lang immun, und ein Priester oder Schamane kann ihre Erneuerung entfernen.",
	["Interrupt her Holy Smite and her heals; a priest or a shaman can remove her shield."] = "Unterbrecht ihre Heilige Pein und ihre Heilungen. Ein Priester oder Schamane kann ihren Schild entfernen.",
	["Interrupt his Chain Lightning. A priest or a shaman can remove his Bloodlust."] = "Unterbrecht seinen Kettenblitzschlag. Ein Priester oder Schamane kann seinen Kampfrausch entfernen.",
	["Interrupt his Chained Bolt, which jumps to a second player."] = "Unterbrecht seinen Verketteten Blitz, der auf einen zweiten Spieler überspringt.",
	["Interrupt his Fear and, at 30% health, his heal. He puts everyone near him to sleep (damage wakes a sleeper), and a mage or a druid can remove his Curse of Blood."] = "Unterbrecht seine Furcht und bei 30% Gesundheit seine Heilung. Er schläfert alle in seiner Nähe ein (Schaden weckt Schlafende auf). Ein Magier oder Druide kann seinen Blutfluch entfernen.",
	["Interrupt his Healing Touch. Thunderclap slows everyone near him."] = "Unterbrecht seine Heilende Berührung. Donnerknall verlangsamt alle in seiner Nähe.",
	["Interrupt his Holy Light. Divine Shield makes him immune for 10 seconds, and he stuns with Hammer of Justice."] = "Unterbrecht sein Heiliges Licht. Gottesschild macht ihn 10 Sekunden lang immun, und mit Hammer der Gerechtigkeit betäubt er.",
	["Interrupt his Immolate or dispel the burn. A mage or a druid can remove his Curse of Weakness."] = "Unterbrecht seinen Feuerbrand oder bannt den Brandeffekt. Ein Magier oder Druide kann seinen Fluch der Schwäche entfernen.",
	["Interrupt his Lightning Bolt and Healing Touch. Below 30% health his serpent form hits harder and puts players to sleep."] = "Unterbrecht seinen Blitzschlag und seine Heilende Berührung. Unter 30% Gesundheit schlägt er in Schlangengestalt härter zu und versetzt Spieler in Schlaf.",
	["Interrupt his Molten Metal, which burns and slows."] = "Unterbrecht sein Geschmolzenes Metall, das verbrennt und verlangsamt.",
	["Interrupt his Void Bolt. He teleports between his ledges, and stuns everyone around him when the tank reaches him."] = "Unterbrecht seinen Leerenblitz. Er teleportiert sich zwischen seinen Vorsprüngen hin und her und betäubt alle um sich herum, wenn der Tank ihn erreicht.",
	["Interrupt his slow Healing Touch and his Lightning Bolt."] = "Unterbrecht seine langsame Heilende Berührung und seinen Blitzschlag.",
	["Interrupt or dispel his Dominate Mind, which takes over a player; interrupt his Shadow Bolt."] = "Unterbrecht oder bannt sein Gedanken beherrschen, das einen Spieler übernimmt; unterbrecht seinen Schattenblitz.",
	["Interrupt or dispel his Polymorph. His Silence reaches 15 yards: healers, stand back."] = "Unterbrecht oder bannt seine Verwandlung. Seine Stille reicht 15 Meter weit: Heiler, haltet Abstand.",
	["Interrupt or dispel his Soul Drain, which roots a player and drains their health."] = "Unterbrecht oder bannt seinen Seelenentzug, der einen Spieler festhält und ihm Gesundheit entzieht.",
	["Into The Scarlet Monastery"] = "Ins Scharlachrote Kloster",
	["Into The Temple of Atal'Hakkar"] = "In den Tempel von Atal'Hakkar",
	["Into the Depths"] = "In die Tiefe",
	["Investigate the disappearance of Edward Heartweaver in Ruins of Lordaeron."] = "Untersucht das Verschwinden von Edward Herzweber in den Ruinen von Lordaeron.",
	["Ironclad Cove"] = "Eisenpanzerbucht",
	["Ironforge"] = "Eisenschmiede",
	["It fears a player and slows another's casting."] = "Er versetzt einen Spieler in Furcht und verlangsamt das Zaubern eines anderen.",
	["It keeps calling small Arcane Manalings. Kill them with area damage."] = "Ruft immer wieder kleine Arkane Manalinge herbei. Tötet sie mit Flächenschaden.",
	["It roots everyone near it, slows and stuns, and calls Dupe Bugs that its Patch turns into healing."] = "Er wurzelt alle in seiner Nähe fest, verlangsamt und betäubt und ruft Duplikatwanzen herbei, die sein Patch in Heilung verwandelt.",
	["It whirls at everyone close, and its thorns hurt whoever strikes it or an ally nearby, Ramtusk included."] = "Er wirbelt auf alle in seiner Nähe ein, und seine Dornen verletzen jeden, der ihn oder einen Verbündeten in seiner Nähe angreift, Rammhauer eingeschlossen.",
	["Item start: Abominable Head, inside Ruins of Lordaeron"] = "Startgegenstand: Abscheulicher Kopf, in den Ruinen von Lordaeron",
	["Item start: Blood-Stained Letter, graveyard inside Ruins of Lordaeron"] = "Startgegenstand: Blutbefleckter Brief, Friedhof in den Ruinen von Lordaeron",
	["Item start: Bloodied Insignia, inside Ruins of Lordaeron"] = "Startgegenstand: Blutbeflecktes Abzeichen, in den Ruinen von Lordaeron",
	["Item start: Crest of Lordaeron, inside Ruins of Lordaeron"] = "Startgegenstand: Wappen von Lordaeron, in den Ruinen von Lordaeron",
	["Item start: Glowing Shard, dropped by Mutanus the Devourer"] = "Beginnt mit Gegenstand: Glühender Splitter, Beute von Mutanus dem Verschlinger",
	["Its Fathom Stone also calls up Baron Aquanis, an optional fight."] = "Der Tiefenstein ruft auch Baron Aquanis herbei, einen optionalen Gegner.",
	["Its attack on the tank between the beams, a 1.5-second cast."] = "Der Angriff auf den Tank zwischen den Strahlen, mit 1.5 Sekunden Zauberzeit.",
	["Jail Break!"] = "Gefängnisausbruch!",
