	["Parqual Fintallas, Undercity"] = "Parqual Fintallas, Unterstadt",
	["Part of the Test of Faith chain, which starts with Dorn Plainstalker in Thousand Needles. The book is on a table in the first room on the left past the courtyard."] = "Teil der Questreihe „Prüfung des Glaubens“, die bei Dorn Ebenenpirscher in Tausend Nadeln beginnt. Das Buch liegt hinter dem Innenhof im ersten Raum links auf einem Tisch.",
	["Part of the chain The Unsent Letter starts, from Edwin VanCleef in the Deadmines."] = "Teil der Questreihe, die mit „Der nicht abgeschickte Brief“ von Edwin VanCleef in den Todesminen beginnt.",
	["Past Atrexis, clear the north-east room with the market stalls and the small pink summoning circle. Whoever carries the tome clicks the circle, and Lyn comes out of the big round grate."] = "Säubert hinter Atrexis den Raum im Nordosten mit den Marktständen und dem kleinen rosa Beschwörungskreis. Wer den Folianten trägt, klickt auf den Kreis, und Lyn kommt aus dem großen runden Gitter.",
	["Past Due"] = "Überfällig",
	["Patrick Garrett, Undercity"] = "Patrick Garrett, Unterstadt",
	["Pit of Fangs"] = "Grube der Giftzähne",
	["Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink."] = "Stellt das Gambit der Morgendämmerung im Aussichtsraum der Scholomance auf. Besiegt Vectus und kehrt dann zu Betina Bigglezink zurück.",
	["Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple."] = "Legt die Essenz von Eranikus in den Essenzbrunnen in diesem Hort im Versunkenen Tempel.",
