	["Put Her Down"] = "Bringt sie zur Strecke",
	["Put a Grime-Encrusted Item into the Sparklematic 5200 to have it cleaned."] = "Legt einen Schmutzverkrusteten Gegenstand in den Funkelmat 5200, um ihn reinigen zu lassen.",
	["Put a Grime-Encrusted Object in the Sparklematic 5200; you need 3 silver to run it."] = "Legt einen Schmutzverkrusteten Gegenstand in den Funkelmat 5200; um ihn zu starten, braucht Ihr 3 Silber.",
	["Put the spirit of Faldrim Anvilmar to rest."] = "Bringt den Geist von Faldrim Ambossar zur Ruhe.",
	["Puts a player to sleep for up to 15 seconds."] = "Versetzt einen Spieler bis zu 15 Sekunden lang in Schlaf.",
	["Puts a player to sleep for up to 20 seconds."] = "Versetzt einen Spieler bis zu 20 Sekunden lang in Schlaf.",
	["Puts a player to sleep for up to 20 seconds. Damage wakes them, and a Magic dispel removes it."] = "Versetzt einen Spieler bis zu 20 Sekunden lang in Schlaf. Schaden weckt ihn auf, und das Bannen von Magie entfernt den Effekt.",
	["Puts a player to sleep."] = "Versetzt einen Spieler in Schlaf.",
	["Puts everyone near him to sleep for up to 10 seconds. Damage wakes a sleeper."] = "Schläfert alle in seiner Nähe bis zu 10 Sekunden lang ein. Schaden weckt Schlafende.",
	["Quell the Uprising"] = "Den Aufstand niederschlagen",
