	["Riverglades"] = "Flussauen",
	["Rocknot's Ale"] = "Rocknots Bier",
	["Roots a player for 10 seconds and drains their health into his. Interrupt the 2-second cast or dispel it."] = "Hält einen Spieler 10 Sekunden lang fest und überträgt dessen Gesundheit auf ihn selbst. Unterbrecht den Zauber (2 Sekunden Zauberzeit) oder bannt ihn.",
